import{_ as t,o as e,c as i,ae as r}from"./chunks/framework.D_KAhcqz.js";const n="/AI/rag-flow.png",s="/AI/rag-chunking.gif",b=JSON.parse('{"title":"RAG 检索增强生成实战","description":"","frontmatter":{"layout":"doc","title":"RAG 检索增强生成实战"},"headers":[],"relativePath":"articles/rag.md","filePath":"articles/rag.md"}'),l={name:"articles/rag.md"};function d(o,a,h,c,g,p){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="rag-检索增强生成实战" tabindex="-1">RAG 检索增强生成实战 <a class="header-anchor" href="#rag-检索增强生成实战" aria-label="Permalink to &quot;RAG 检索增强生成实战&quot;">​</a></h1><p>RAG（Retrieval-Augmented Generation，检索增强生成）是解决大模型“知识滞后”与“幻觉”问题的核心技术，通过将“检索外部知识库”与“大模型生成”相结合，让 AI 能够基于最新、最精准的私有数据回答问题。在企业知识库问答、文档助手、垂直领域咨询等场景中，RAG 已成为落地必备方案。</p><h2 id="一、rag-核心原理" tabindex="-1">一、RAG 核心原理 <a class="header-anchor" href="#一、rag-核心原理" aria-label="Permalink to &quot;一、RAG 核心原理&quot;">​</a></h2><p>RAG 的本质是“先检索，后生成”，通过检索模块为大模型提供精准的上下文支撑，避免模型依赖过期的预训练知识或编造信息。其核心流程可分为五步：</p><div style="text-align:center;margin:2rem 0;"><img src="'+n+'" alt="RAG核心流程图" style="width:80%;border-radius:12px;box-shadow:0 4px 16px rgba(0,0,0,0.1);"></div><ol><li><strong>文档加载</strong>：导入 PDF、Word、Markdown 等格式的私有文档；</li><li><strong>文档预处理</strong>：拆分文档为片段（Chunking）、提取关键信息，避免文本过长；</li><li><strong>向量转换</strong>：通过嵌入模型（Embedding）将文本片段转为向量（Vector）；</li><li><strong>检索匹配</strong>：用户提问后，检索向量数据库中最相关的文本片段；</li><li><strong>生成回答</strong>：将检索结果与提问一起传给大模型，生成精准回答。</li></ol><h2 id="二、rag-技术栈选型" tabindex="-1">二、RAG 技术栈选型 <a class="header-anchor" href="#二、rag-技术栈选型" aria-label="Permalink to &quot;二、RAG 技术栈选型&quot;">​</a></h2><p>搭建生产级 RAG 系统，需合理选择以下核心组件：</p><h3 id="_1-文档加载工具" tabindex="-1">1. 文档加载工具 <a class="header-anchor" href="#_1-文档加载工具" aria-label="Permalink to &quot;1. 文档加载工具&quot;">​</a></h3><ul><li><strong>LangChain Document Loaders</strong>：支持 100+ 文档格式，适配 PDF/Word/Excel/网页等；</li><li><strong>Unstructured</strong>：擅长复杂格式文档解析（如多栏、图文混排 PDF）。</li></ul><h3 id="_2-文本拆分策略" tabindex="-1">2. 文本拆分策略 <a class="header-anchor" href="#_2-文本拆分策略" aria-label="Permalink to &quot;2. 文本拆分策略&quot;">​</a></h3><ul><li><strong>按字符长度拆分</strong>：基础方案，适合普通文本（如每段 500 字）；</li><li><strong>按语义拆分</strong>：基于句子边界或段落，避免拆分语义单元（推荐使用 LangChain 的 RecursiveCharacterTextSplitter）。</li></ul><div style="text-align:center;margin:2rem 0;"><img src="'+s+`" alt="文本拆分示意图" style="width:75%;border-radius:12px;"></div><h3 id="_3-嵌入模型-embedding" tabindex="-1">3. 嵌入模型（Embedding） <a class="header-anchor" href="#_3-嵌入模型-embedding" aria-label="Permalink to &quot;3. 嵌入模型（Embedding）&quot;">​</a></h3><ul><li><strong>开源模型</strong>：Sentence-BERT（all-MiniLM-L6-v2）、BGE，适合本地部署；</li><li><strong>API 模型</strong>：OpenAI Embeddings、通义千问 Embeddings，适合快速落地。</li></ul><h3 id="_4-向量数据库" tabindex="-1">4. 向量数据库 <a class="header-anchor" href="#_4-向量数据库" aria-label="Permalink to &quot;4. 向量数据库&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数据库</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td>Pinecone</td><td>云原生、无需运维</td><td>快速验证、中小规模项目</td></tr><tr><td>Milvus</td><td>开源、高吞吐</td><td>大规模私有化部署</td></tr><tr><td>Chroma</td><td>轻量、易部署</td><td>本地开发、小型项目</td></tr><tr><td>Redis</td><td>支持向量存储+缓存</td><td>已有 Redis 生态的项目</td></tr></tbody></table><h3 id="_5-大模型选择" tabindex="-1">5. 大模型选择 <a class="header-anchor" href="#_5-大模型选择" aria-label="Permalink to &quot;5. 大模型选择&quot;">​</a></h3><ul><li>通用场景：GPT-3.5/4、通义千问、文心一言；</li><li>私有化场景：Llama 2、Qwen-7B/14B（需部署本地）。</li></ul><h2 id="三、实战项目-企业知识库智能问答系统" tabindex="-1">三、实战项目：企业知识库智能问答系统 <a class="header-anchor" href="#三、实战项目-企业知识库智能问答系统" aria-label="Permalink to &quot;三、实战项目：企业知识库智能问答系统&quot;">​</a></h2><p>以“某科技公司内部知识库问答”为例，完整实现 RAG 流程：</p><h3 id="_1-环境搭建" tabindex="-1">1. 环境搭建 <a class="header-anchor" href="#_1-环境搭建" aria-label="Permalink to &quot;1. 环境搭建&quot;">​</a></h3><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 安装核心依赖</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pip install langchain openai pinecone</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client sentence</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transformers pypdf</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div>`,23)])])}const m=t(l,[["render",d]]);export{b as __pageData,m as default};
